import React, { useMemo, useState } from 'react';
import './CheckoutPage.css';

export interface CartItem {
  id: string;
  name: string;
  imageUrl: string;
  unitPrice: number; // in the smallest meaningful unit, e.g. dollars
  quantity: number;
}

export interface DeliveryAddress {
  fullName: string;
  street: string;
  city: string;
  postalCode: string;
  country: string;
  phone: string;
}

interface CheckoutPageProps {
  cartItems: CartItem[];
  onBackToCart: () => void;
  onPay: (address: DeliveryAddress) => Promise<void> | void;
  currency?: string;
}

type AddressErrors = Partial<Record<keyof DeliveryAddress, string>>;

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  street: '',
  city: '',
  postalCode: '',
  country: '',
  phone: '',
};

function formatPrice(amount: number, currency: string): string {
  return new Intl.NumberFormat(undefined, {
    style: 'currency',
    currency,
  }).format(amount);
}

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};

  if (!address.fullName.trim()) {
    errors.fullName = 'Full name is required.';
  }
  if (!address.street.trim()) {
    errors.street = 'Street address is required.';
  }
  if (!address.city.trim()) {
    errors.city = 'City is required.';
  }
  if (!address.postalCode.trim()) {
    errors.postalCode = 'Postal code is required.';
  }
  if (!address.country.trim()) {
    errors.country = 'Country is required.';
  }
  if (!address.phone.trim()) {
    errors.phone = 'Phone number is required.';
  } else if (!/^[\d\s+()-]{6,}$/.test(address.phone.trim())) {
    errors.phone = 'Enter a valid phone number.';
  }

  return errors;
}

export default function CheckoutPage({
  cartItems,
  onBackToCart,
  onPay,
  currency = 'USD',
}: CheckoutPageProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<AddressErrors>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);

  const subtotal = useMemo(
    () => cartItems.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0),
    [cartItems]
  );

  const shipping = cartItems.length > 0 ? 5 : 0;
  const total = subtotal + shipping;

  const handleChange =
    (field: keyof DeliveryAddress) =>
    (event: React.ChangeEvent<HTMLInputElement>) => {
      const value = event.target.value;
      setAddress((prev) => ({ ...prev, [field]: value }));
      setErrors((prev) => ({ ...prev, [field]: undefined }));
    };

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setSubmitError(null);

    const validationErrors = validateAddress(address);
    setErrors(validationErrors);

    if (Object.keys(validationErrors).length > 0) {
      return;
    }

    if (cartItems.length === 0) {
      setSubmitError('Your cart is empty.');
      return;
    }

    try {
      setIsSubmitting(true);
      await onPay(address);
    } catch (err) {
      setSubmitError('Payment failed. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="checkout-page">
      <div className="checkout-header">
        <button
          type="button"
          className="back-link"
          onClick={onBackToCart}
          aria-label="Back to cart"
        >
          &larr; Back to cart
        </button>
        <h1>Checkout</h1>
      </div>

      <div className="checkout-layout">
        <section className="cart-summary" aria-labelledby="cart-summary-heading">
          <h2 id="cart-summary-heading">Your order</h2>

          {cartItems.length === 0 ? (
            <p className="empty-cart">Your cart is empty.</p>
          ) : (
            <ul className="cart-item-list">
              {cartItems.map((item) => (
                <li className="cart-item" key={item.id}>
                  <img
                    className="cart-item-image"
                    src={item.imageUrl}
                    alt={item.name}
                  />
                  <div className="cart-item-details">
                    <span className="cart-item-name">{item.name}</span>
                    <span className="cart-item-qty">Qty: {item.quantity}</span>
                  </div>
                  <span className="cart-item-price">
                    {formatPrice(item.unitPrice * item.quantity, currency)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <div className="totals">
            <div className="totals-row">
              <span>Subtotal</span>
              <span>{formatPrice(subtotal, currency)}</span>
            </div>
            <div className="totals-row">
              <span>Shipping</span>
              <span>{formatPrice(shipping, currency)}</span>
            </div>
            <div className="totals-row totals-row-grand">
              <span>Total</span>
              <span>{formatPrice(total, currency)}</span>
            </div>
          </div>
        </section>

        <section className="address-section" aria-labelledby="address-heading">
          <h2 id="address-heading">Delivery address</h2>

          <form className="address-form" onSubmit={handleSubmit} noValidate>
            <div className="form-field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                value={address.fullName}
                onChange={handleChange('fullName')}
                aria-invalid={Boolean(errors.fullName)}
                aria-describedby={errors.fullName ? 'fullName-error' : undefined}
              />
              {errors.fullName && (
                <span className="field-error" id="fullName-error">
                  {errors.fullName}
                </span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="street">Street address</label>
              <input
                id="street"
                type="text"
                value={address.street}
                onChange={handleChange('street')}
                aria-invalid={Boolean(errors.street)}
                aria-describedby={errors.street ? 'street-error' : undefined}
              />
              {errors.street && (
                <span className="field-error" id="street-error">
                  {errors.street}
                </span>
              )}
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  value={address.city}
                  onChange={handleChange('city')}
                  aria-invalid={Boolean(errors.city)}
                  aria-describedby={errors.city ? 'city-error' : undefined}
                />
                {errors.city && (
                  <span className="field-error" id="city-error">
                    {errors.city}
                  </span>
                )}
              </div>

              <div className="form-field">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  value={address.postalCode}
                  onChange={handleChange('postalCode')}
                  aria-invalid={Boolean(errors.postalCode)}
                  aria-describedby={
                    errors.postalCode ? 'postalCode-error' : undefined
                  }
                />
                {errors.postalCode && (
                  <span className="field-error" id="postalCode-error">
                    {errors.postalCode}
                  </span>
                )}
              </div>
            </div>

            <div className="form-field">
              <label htmlFor="country">Country</label>
              <input
                id="country"
                type="text"
                value={address.country}
                onChange={handleChange('country')}
                aria-invalid={Boolean(errors.country)}
                aria-describedby={errors.country ? 'country-error' : undefined}
              />
              {errors.country && (
                <span className="field-error" id="country-error">
                  {errors.country}
                </span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="phone">Phone number</label>
              <input
                id="phone"
                type="tel"
                value={address.phone}
                onChange={handleChange('phone')}
                aria-invalid={Boolean(errors.phone)}
                aria-describedby={errors.phone ? 'phone-error' : undefined}
              />
              {errors.phone && (
                <span className="field-error" id="phone-error">
                  {errors.phone}
                </span>
              )}
            </div>

            {submitError && <div className="submit-error">{submitError}</div>}

            <div className="checkout-actions">
              <button
                type="button"
                className="btn btn-secondary"
                onClick={onBackToCart}
                disabled={isSubmitting}
              >
                Back to cart
              </button>
              <button
                type="submit"
                className="btn btn-primary"
                disabled={isSubmitting || cartItems.length === 0}
              >
                {isSubmitting ? 'Processing…' : `Pay ${formatPrice(total, currency)}`}
              </button>
            </div>
          </form>
        </section>
      </div>
    </div>
  );
}
```

